mapper.select:
select r.report_no as reportNo, r.order_no as orderNo, r.operation_code as operationCode,
       r.serial_no as serialNo, r.qualified_qty as qualifiedQty, r.unqualified_qty as unqualifiedQty,
       r.scrap_qty as scrapQty, r.operator_no as operatorNo, r.reported_at as reportedAt
from ex_production_report r

    and r.order_no like concat('%', #{orderNo}, '%')
    and r.operator_no = #{operatorNo}
    and r.reported_at >= #{beginTime}
    and r.reported_at <= #{endTime}

order by r.reported_at desc

select o.order_no as orderNo, o.product_code as productCode, o.status as status, o.planned_qty as plannedQty, o.completed_qty as completedQty, o.qualified_qty as qualifiedQty, o.scrap_qty as scrapQty, o.kit_status as kitStatus from wo_production_order o
and o.order_no like concat('%', #{orderNo}, '%') and o.status = #{status}
order by o.id desc

select c.consume_no as consumeNo, c.order_no as orderNo, c.material_code as materialCode, c.material_batch_no as materialBatchNo, c.serial_no as serialNo, c.consumed_qty as consumedQty, c.sync_status as syncStatus, c.consumed_at as consumedAt from mt_material_consumption c
and c.order_no like concat('%', #{orderNo}, '%') and c.material_code = #{materialCode}
order by c.consumed_at desc

select i.inspection_no as inspectionNo, i.inspection_type as inspectionType, i.order_no as orderNo, i.operation_code as operationCode, i.serial_no as serialNo, i.result as result, i.inspector_no as inspectorNo, i.inspected_at as inspectedAt from qc_inspection i
and i.inspection_type = #{inspectionType} and i.result = #{result}
order by i.inspected_at desc
